    private static void TableWriteShipCreate(TableWriter w, ShipCreate value)
    {
        if (value.ShipType != ShipType.None)
        {
            w.U16(0x38e9); // ship_type
            w.U8(6);
            w.U8((byte)value.ShipType);
        }
        {
            int fieldAt = w.Len;
            w.U16(0xdd45); // position
            w.U8(13);
            int lenAt = w.Len;
            w.U32(0);
            TableWriteQuantizedPosition(w, value.Position);
            if (w.Len - lenAt - 4 <= 2)
            {
                w.Len = fieldAt; // all-default nested elides
            }
            else
            {
                w.Patch32(lenAt, (uint)(w.Len - lenAt - 4));
            }
        }
        {
            int fieldAt = w.Len;
            w.U16(0x60f3); // rotation
            w.U8(13);
            int lenAt = w.Len;
            w.U32(0);
            TableWriteQuantizedRotation(w, value.Rotation);
            if (w.Len - lenAt - 4 <= 2)
            {
                w.Len = fieldAt; // all-default nested elides
            }
            else
            {
                w.Patch32(lenAt, (uint)(w.Len - lenAt - 4));
            }
        }
        {
            int fieldAt = w.Len;
            w.U16(0x0637); // linear_velocity
            w.U8(13);
            int lenAt = w.Len;
            w.U32(0);
            TableWriteQuantizedVelocity(w, value.LinearVelocity);
            if (w.Len - lenAt - 4 <= 2)
            {
                w.Len = fieldAt; // all-default nested elides
            }
            else
            {
                w.Patch32(lenAt, (uint)(w.Len - lenAt - 4));
            }
        }
        if (value.HasFlags != false)
        {
            w.U16(0xaa8d); // has_flags
            w.U8(1);
            if (value.HasFlags)
            {
                w.U8(1);
            }
            else
            {
                w.U8(0);
            }
        }
        if (value.HasFlags)
        {
            if (value.Flags != 0)
            {
                w.U16(0xe64b); // flags
                w.U8(9);
                w.U64((ulong)value.Flags);
            }
        }
        if (value.Team != Team.None)
        {
            w.U16(0xdff1); // team
            w.U8(6);
            w.U8((byte)value.Team);
        }
        if (value.Health != 0)
        {
            w.U16(0x8617); // health
            w.U8(3);
            w.U16((ushort)value.Health);
        }
        if (value.Thrust != 0)
        {
            w.U16(0x9e51); // thrust
            w.U8(2);
            w.U8((byte)value.Thrust);
        }
        w.U16(0); // terminator
    }

    // TableReadShipCreate decodes a table-wire buffer under the permissive contract:
    // declared defaults prefill, known fields overlay, unknown ids and kind
    // mismatches skip and count, out-of-range values clamp and count. false
    // means malformed — the partial decode up to that point is kept.
    public static bool TableReadShipCreate(byte[] data, ref ShipCreate value, TableReport report)
    {
        TableReader r = new TableReader(data, 0, data.Length, report);
        return TableReadShipCreate(r, ref value);
    }

    private static bool TableReadShipCreate(TableReader r, ref ShipCreate value)
    {
        value = new ShipCreate(); // prefill declared defaults, then overlay
        while (true)
        {
            if (!r.Has(2))
            {
                r.Report.Malformed = true;
                return false;
            }
            ushort fieldId = r.Get16();
            if (fieldId == 0)
            {
                return true;
            }
            if (!r.Has(1))
            {
                r.Report.Malformed = true;
                return false;
            }
            byte kind = r.Get8();
            switch (fieldId)
            {
                case 0x38e9: // ship_type
                {
                    if (kind != 6)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(1))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    byte raw = r.Get8();
                    if (raw > 5)
                    {
                        raw = 0; // out-of-set -> None
                        r.Report.Clamped++;
                    }
                    value.ShipType = (ShipType)raw;
                    break;
                }
                case 0xdd45: // position
                {
                    if (kind != 13)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(4))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    int bodyLen = (int)r.Get32();
                    if (!r.Has(bodyLen))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    TableReader sub = new TableReader(r.Buf, r.Off, r.Off + bodyLen, r.Report);
                    TableReadQuantizedPosition(sub, ref value.Position);
                    r.Off += bodyLen;
                    break;
                }
                case 0x60f3: // rotation
                {
                    if (kind != 13)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(4))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    int bodyLen = (int)r.Get32();
                    if (!r.Has(bodyLen))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    TableReader sub = new TableReader(r.Buf, r.Off, r.Off + bodyLen, r.Report);
                    TableReadQuantizedRotation(sub, ref value.Rotation);
                    r.Off += bodyLen;
                    break;
                }
                case 0x0637: // linear_velocity
                {
                    if (kind != 13)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(4))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    int bodyLen = (int)r.Get32();
                    if (!r.Has(bodyLen))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    TableReader sub = new TableReader(r.Buf, r.Off, r.Off + bodyLen, r.Report);
                    TableReadQuantizedVelocity(sub, ref value.LinearVelocity);
                    r.Off += bodyLen;
                    break;
                }
                case 0xaa8d: // has_flags
                {
                    if (kind != 1)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(1))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    value.HasFlags = r.Get8() != 0;
                    break;
                }
                case 0xe64b: // flags
                {
                    if (kind != 9)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(8))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    value.Flags = r.Get64();
                    break;
                }
                case 0xdff1: // team
                {
                    if (kind != 6)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(1))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    byte raw = r.Get8();
                    if (raw > 2)
                    {
                        raw = 0; // out-of-set -> None
                        r.Report.Clamped++;
                    }
                    value.Team = (Team)raw;
                    break;
                }
                case 0x8617: // health
                {
                    if (kind != 3)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(2))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    short decoded = (short)r.Get16();
                    if (decoded < 0)
                    {
                        decoded = 0;
                        r.Report.Clamped++;
                    }
                    else if (decoded > 1000)
                    {
                        decoded = 1000;
                        r.Report.Clamped++;
                    }
                    value.Health = (short)decoded;
                    break;
                }
                case 0x9e51: // thrust
                {
                    if (kind != 2)
                    {
                        r.Report.KindMismatch++;
                        if (!r.Skip(kind))
                        {
                            r.Report.Malformed = true;
                            return false;
                        }
                        break;
                    }
                    if (!r.Has(1))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    sbyte decoded = (sbyte)r.Get8();
                    if (decoded < 0)
                    {
                        decoded = 0;
                        r.Report.Clamped++;
                    }
                    else if (decoded > 100)
                    {
                        decoded = 100;
                        r.Report.Clamped++;
                    }
                    value.Thrust = (sbyte)decoded;
                    break;
                }
                default:
                {
                    r.Report.Unknown++;
                    if (!r.Skip(kind))
                    {
                        r.Report.Malformed = true;
                        return false;
                    }
                    break;
                }
            }
        }
    }
}
